// Copies the few Lucide icons the landing, auth pages and app use out of @iconify-json/lucide (a dev
// dependency) into src/icons.ts, so pages need no runtime icon request and no 1,600-icon JSON in the bundle.
// Lucide is ISC-licensed: the notice travels in the generated file; no on-page credit is needed.
// (Until 2026-11-13 this was Solar, CC BY 4.0, which needed a credit line in the landing footer.)
// Run from apps/web after changing the list: node scripts/icons.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const set = require("@iconify-json/lucide/icons.json");
const info = require("@iconify-json/lucide/info.json");
const pkg = require("@iconify-json/lucide/package.json");

const NAMES = {
  read: "file-text",
  run: "play",
  submit: "upload",
  unlock: "lock-open",
  hidden: "eye-off",
  calendar: "calendar-check",
  lesson: "book-open",
  hint: "lightbulb",
  judge: "cpu",
  limits: "timer",
  streak: "flame",
  archive: "archive",
  invite: "ticket",
  login: "log-in",
  arrow: "arrow-right",
  menu: "menu",
  close: "x",
  show: "eye",
  check: "circle-check",
  caps: "keyboard",
  lock: "lock",
  clock: "clock",
  sun: "sun",
  moon: "moon",
  auto: "monitor",
  laptop: "laptop",
  shuffle: "shuffle",
  chevron: "chevron-down",
  user: "circle-user",
  pen: "pen-line",
  compare: "arrow-left-right",
  code: "code",
  warn: "triangle-alert",
};

// Lucide draws at stroke 2 on a 24 grid; 1.75 sits closer to the UI's 1.5–2px outlines at 14–20px.
const lines = Object.entries(NAMES).map(([key, name]) => {
  const icon = set.icons[name] ?? set.icons[set.aliases?.[name]?.parent]; // some names are aliases now
  if (!icon) throw new Error(`Lucide has no icon "${name}"`);
  if ((icon.width ?? set.width ?? 24) !== 24) throw new Error(`${name} is not on a 24 grid`);
  return `  ${key}: ${JSON.stringify(icon.body.replaceAll('stroke-width="2"', 'stroke-width="1.75"'))},`;
});

const out = `// Generated by scripts/icons.mjs — do not edit by hand.
// Icons: Lucide (${info.author.url}), ${info.license.title}, via Iconify, @iconify-json/lucide ${pkg.version}.
// ISC License: Copyright (c) for portions of Lucide are held by Cole Bemis 2013-2022 as part of Feather (MIT).
// All other copyright (c) for Lucide are held by Lucide Contributors 2022. Permission to use, copy, modify,
// and/or distribute this software for any purpose with or without fee is hereby granted, provided that the
// above copyright notice and this permission notice appear in all copies.
export const ICONS = {
${lines.join("\n")}
} as const;

export type IconName = keyof typeof ICONS;
`;

const target = new URL("../src/icons.ts", import.meta.url);
let before = "";
try { before = readFileSync(target, "utf8"); } catch {}
if (before !== out) writeFileSync(target, out);
console.log(`icons.ts: ${lines.length} icons`);
